// Хороший фрагмент: безопасное использование API с подготовленными выражениями
public String getUserData(String input) {
    String query = "SELECT * FROM users WHERE username = ?";
    // Использование подготовленного выражения для предотвращения SQL-инъекций
    return executePreparedStatement(query, input);
}
