import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class VulnerableAPIUsage {

    public static void main(String[] args) {
        // Vulnerabile: Non si verifica la validità dell'URL e non si gestiscono errori
        String url = "http://api.example.com/data?param=" + args[0]; // Parametro non filtrato

        try {
            URL obj = new URL(url);
            HttpURLConnection con = (HttpURLConnection) obj.openConnection();

            // Invio della richiesta senza controllo del metodo HTTP o dei headers
            con.setRequestMethod("GET");

            BufferedReader in = new BufferedReader(
                    new InputStreamReader(con.getInputStream()));
            String inputLine;
            StringBuilder response = new StringBuilder();

            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();

            System.out.println(response.toString());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
