```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class SecureAPIUsage {

    public static void main(String[] args) {
        // Controllo che un parametro sia fornito
        if (args.length == 0) {
            System.err.println("Parametro mancante.");
            return;
        }

        // Filtraggio del parametro per evitare attacchi di tipo injection
        String param = args[0].replaceAll("[^a-zA-Z0-9_]", "");

        // Costruzione URL sicura
        String url = "http://api.example.com/data?param=" + param;

        try {
            URL obj = new URL(url);
            HttpURLConnection con = (HttpURLConnection) obj.openConnection();

            // Impostazione del metodo HTTP e header necessari
            con.setRequestMethod("GET");
            con.setRequestProperty("User-Agent", "Java/1.8");

            // Gestione risposta
            BufferedReader in = new BufferedReader(
                    new InputStreamReader(con.getInputStream()));
            String inputLine;
            StringBuilder response = new StringBuilder();

            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();

            System.out.println(response.toString());
        } catch (Exception e) {
            System.err.println("Errore durante la richiesta API: " + e.getMessage());
        }
    }
}
```

