// Corretto: utilizzo della valutazione sicura e gestione delle eccezioni appropriata
public class SafeServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String input = request.getParameter("input");

        // Valida l'input prima di usarlo
        if (isValidInput(input)) {
            try {
                // Esegui solo operazioni specifiche e note
                executeSafeOperation(input);
            } catch (Exception e) {
                // Logga l'errore in modo sicuro e informa l'utente con un messaggio generico
                logger.error("Errore durante l'esecuzione dell'operazione", e);
                response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Si è verificato un errore.");
            }
        } else {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Input non valido.");
        }
    }

    private boolean isValidInput(String input) {
        // Esempio semplice di validazione: controllo lunghezza massima
        return input != null && input.length() <= 100;
    }

    private void executeSafeOperation(String input) {
        // Esempio: esegui un comando predefinito e noto
        if ("safeCommand".equals(input)) {
            System.out.println("Operazione eseguita in modo sicuro.");
        } else {
            throw new IllegalArgumentException("Comando non riconosciuto.");
        }
    }
}
